/* @lc app=leetcode id=3160 lang=kotlin */
class Solution { fun queryResults(limit: Int, queries: Array<IntArray>): IntArray = HashMap<Int, Int>().let { ballMap -> HashMap<Int, Int>().let { colorMap -> IntArray(queries.size) { i -> queries[i].let { (b, c) -> ballMap[b]?.let { old -> colorMap[old]?.let { if (it == 1) colorMap.remove(old) else colorMap[old] = it - 1 } }.also { ballMap[b] = c }.also { colorMap[c] = (colorMap[c] ?: 0) + 1 }.run { colorMap.size } } } } } }